package org.rabochaya.projects;
import android.app.Activity;import android.graphics.*;import android.view.View;
/** Local-only read-only graph; missing samples break the line. */
public final class DemProfileView extends View {
 private final DemProfile profile;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final float density;
 public DemProfileView(Activity activity,DemProfile profile){super(activity);this.profile=profile;density=getResources().getDisplayMetrics().density;paint.setTypeface(WorkspaceUi.font(activity));setContentDescription("График высоты DEM; пропуски означают отсутствие данных");}
 protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.drawColor(0xff232d1d);float left=64*density,right=getWidth()-12*density,top=16*density,bottom=getHeight()-30*density;if(right<=left||bottom<=top)return;paint.setStrokeWidth(density);paint.setColor(0xffaab5a4);canvas.drawLine(left,top,left,bottom,paint);canvas.drawLine(left,bottom,right,bottom,paint);paint.setTextSize(11*density);canvas.drawText("0",left,bottom+18*density,paint);String end=String.format(java.util.Locale.US,"%.2f км",profile.length/1000);canvas.drawText(end,Math.max(left,right-paint.measureText(end)),bottom+18*density,paint);if(profile.valid==0){canvas.drawText("Нет данных",left+8*density,top+20*density,paint);return;}double low=profile.min,high=profile.max;if(high==low){low-=1;high+=1;}canvas.drawText(String.format(java.util.Locale.US,"%.0f м",high),2*density,top+10*density,paint);canvas.drawText(String.format(java.util.Locale.US,"%.0f м",low),2*density,bottom,paint);paint.setColor(0xff39baff);paint.setStrokeWidth(2*density);boolean previous=false;float px=0,py=0;for(int i=0;i<profile.height.length;i++){if(Double.isNaN(profile.height[i])){previous=false;continue;}float x=left+(right-left)*(float)(profile.distance[i]/profile.length),y=bottom-(bottom-top)*(float)((profile.height[i]-low)/(high-low));if(previous)canvas.drawLine(px,py,x,y,paint);canvas.drawCircle(x,y,1.5f*density,paint);px=x;py=y;previous=true;}}
}
